// Support Fins (https://github.com/gittrahan/support-fins, MIT) in the web edition: the
// breakaway support fins that make a tipped-over orientation printable, generated by
// Support Fins' own engine (vendored by packaging/update_support_fins.py, unmodified).
import { GeometryError, weld, manifoldFromArrays, shells } from './geom.js';
import { Manifold } from './wasm.js';

let SF = null, INFO = null, failed = null;

/** Load the engine (the worker does this at start, so features can run synchronously). */
export async function load() {
  if (SF || failed) return;
  try {
    SF = await import('../vendor/support-fins/engine.esm.js');
    INFO = (await import('../vendor/support-fins/version.js')).default;
  } catch (e) { failed = e; }
}

function engine() {
  if (!SF) throw new GeometryError('The Support Fins engine didn’t load. Reload the page and try again.');
  return SF;
}

/** Settings schema (Support Fins' options.json) and which release this is. */
export function info() {
  const sf = engine();
  return { schema: sf.OPTIONS_SCHEMA, version: INFO.version, tag: INFO.tag, commit: INFO.commit, source: INFO.source };
}

/** The body's triangles as the float64 soup Support Fins takes (9 numbers per face). */
function soupOf(v, f) {
  const s = new Float64Array(f.length * 3);
  for (let i = 0; i < f.length; i++) { const p = f[i] * 3; s[i * 3] = v[p]; s[i * 3 + 1] = v[p + 1]; s[i * 3 + 2] = v[p + 2]; }
  return s;
}

/** Fin triangles (seated frame) -> closed solids in our frame, one per piece. */
function solidsOf(tris, offset, ranges) {
  const out = [];
  let skipped = 0;
  for (const rs of ranges) {
    let n = 0;
    for (const [a, b] of rs) n += b - a;
    const v = new Float32Array(n * 9);
    let o = 0;
    for (const [a, b] of rs) for (let t = a; t < b; t++) for (let k = 0; k < 9; k++) v[o++] = tris[t * 9 + k] - (k % 3 === 0 ? offset.x : k % 3 === 1 ? offset.y : offset.z);
    const w = weld(v, Uint32Array.from({ length: n * 3 }, (_, i) => i), 1e-5);
    let m = manifoldFromArrays(w.v, w.f);
    if (!m) {
      // a piece made of several closed shells
      const parts = shells(w.v, w.f).map(s => manifoldFromArrays(s.v, s.f)).filter(Boolean);
      m = parts.length ? Manifold.union(parts) : null;
    }
    if (m && !m.isEmpty()) out.push(m); else skipped++;
  }
  return { solids: out, skipped };
}

/**
 * Support Fins under a posed body.
 * @param {{v: Float32Array, f: Uint32Array}} mesh  the body as it will print (z up)
 * @param {object} values  dialog values keyed as in options.json, in the engine's units
 * @returns {{solids: Manifold[], skipped: number, stats, report: string, over: number[], small: number[], version}}
 */
export function fins(mesh, values) {
  const sf = engine();
  let opts;
  try { opts = sf.optionsFromDialog(values || {}); } catch (e) { throw new GeometryError(`Support Fins setting: ${e.message}`); }
  const r = sf.computeFins(soupOf(mesh.v, mesh.f), opts);
  const { solids, skipped } = solidsOf(r.triangles, r.offset, r.pieces.map(p => p.ranges));
  return { solids, skipped, stats: r.stats, report: sf.reportLine(r.stats), over: Array.from(r.overFaces), small: Array.from(r.smallFaces), version: INFO.version };
}

/** One hand-drawn wall between two points on the body (Support Fins' Draw mode). */
export function wall(mesh, a, b, values) {
  const sf = engine();
  let opts;
  try { opts = sf.optionsFromDialog(values || {}); } catch (e) { throw new GeometryError(`Support Fins setting: ${e.message}`); }
  const r = sf.drawWall(soupOf(mesh.v, mesh.f), a, b, opts);
  if (!r.ok) throw new GeometryError(r.reason || 'Support Fins couldn’t place a wall there.');
  const n = r.triangles.length / 9;
  const { solids } = solidsOf(r.triangles, r.offset, [[[0, n]]]);
  if (!solids.length) throw new GeometryError('Support Fins made a wall that isn’t a closed solid.');
  return { solids, stats: r.stats, version: INFO.version };
}
